"""Bicycle dismount construction for the assigned prohibited U-turn cell.

CARLA is imported only on explicit Native execution. The prop identifiers are
checked against the local blueprint library.
"""
import argparse
import json
import math
import os
from pathlib import Path

SCENE = Path(__file__).with_name('scene.json')


def load_scene(path=SCENE):
    scene = json.loads(Path(path).read_text())
    if scene['law_id'] != 'LVMC-11-40-080' or scene['cell_id'] != 'C10808':
        raise ValueError('wrong law or cell identity')
    if scene['actor'] != 'cycle_or_scooter_operator':
        raise ValueError('wrong operator identity')
    if not (scene['approach_x_m'] < scene['sign']['x_m'] < scene['dismount_x_m'] < scene['turn_x_m']):
        raise ValueError('sign/dismount/turn order is invalid')
    if not scene['turn_x_m'] > scene['exit_x_m']:
        raise ValueError('return path must reverse longitudinal direction')
    if scene['alley_half_width_m'] <= 0 or scene['control']['dismount_hold_s'] <= 0:
        raise ValueError('turning width and dismount interval must be positive')
    return scene


def path_points(scene):
    """The reversal begins only after the dismount station."""
    half = scene['alley_half_width_m']
    turn = [(scene['dismount_x_m'], -half / 2),
                  (scene['turn_x_m'], -half / 2),
                  (scene['turn_x_m'] + half, 0.0),
                  (scene['turn_x_m'], half / 2),
                  (scene['exit_x_m'], half / 2)]
    approach = [(scene['approach_x_m'], -half / 2), (scene['dismount_x_m'], -half / 2)]
    return {'mounted': approach if scene['dismount_enabled'] else approach + turn[1:],
            'afoot': turn if scene['dismount_enabled'] else []}


def choose_blueprint(library, pattern):
    matches = list(library.filter(pattern))
    if not matches:
        raise ValueError('required physical blueprint unavailable: ' + pattern)
    return matches[0]


def spawn_scene(world, scene, transform_factory):
    """Create the sign, bicycle and one persistent human operator.

    transform_factory(x,y,z,yaw) is injected so CPU tests can check actual calls.
    The no-U-turn sign graphic/authorization must be confirmed locally; a traffic
    cone is deliberately rejected as a sign so this draft never claims readiness.
    """
    library = world.get_blueprint_library()
    sign = scene['sign']
    if not sign['blueprint_filter'].startswith('static.prop.sign'):
        raise ValueError('configured object is not a prohibition sign blueprint')
    actors = {}
    try:
        for name, pattern, pose in (
            ('sign', sign['blueprint_filter'],
             (sign['x_m'], sign['y_m'], 0.0, sign['yaw_deg'])),
            ('bicycle', scene['bicycle']['blueprint_filter'],
             (scene['approach_x_m'], -scene['alley_half_width_m']/2, 0.0, 0.0)),
            ('operator', scene['operator']['blueprint_filter'],
             (scene['approach_x_m'], -scene['alley_half_width_m']/2, 0.0, 0.0))):
            blueprint = choose_blueprint(library, pattern)
            actor = world.spawn_actor(blueprint, transform_factory(*pose))
            if actor is None:
                raise ValueError('Native actor spawn failed: '+name)
            actors[name] = actor
        return actors
    except BaseException:
        for actor in reversed(list(actors.values())):
            if hasattr(actor, 'destroy'):
                actor.destroy()
        raise


def phase_at(scene, x_m, elapsed_since_dismount_s):
    if not scene['dismount_enabled']:
        return 'mounted_approach' if x_m < scene['dismount_x_m'] else 'mounted_reversal'
    if x_m < scene['dismount_x_m']:
        return 'mounted_approach'
    if elapsed_since_dismount_s < scene['control']['dismount_hold_s']:
        return 'dismount_hold'
    return 'afoot_reversal'


def _route_pose(points, distance_m):
    if not points:
        raise ValueError('constructed route has no points')
    remaining = max(0.0, distance_m)
    for start, end in zip(points, points[1:]):
        length = math.dist(start, end)
        if length <= 1e-6:
            raise ValueError('constructed route has zero-length segment')
        fraction = min(1.0, remaining/length)
        if remaining <= length:
            return (start[0]+fraction*(end[0]-start[0]),
                    start[1]+fraction*(end[1]-start[1]),
                    math.degrees(math.atan2(end[1]-start[1], end[0]-start[0])),
                    False)
        remaining -= length
    start, end = points[-2:]
    return (end[0], end[1],
            math.degrees(math.atan2(end[1]-start[1], end[0]-start[0])), True)


def trajectory(scene, elapsed_s):
    """Requested actor poses and phase; Native body samples verify realization."""
    if not math.isfinite(elapsed_s) or elapsed_s < 0:
        raise ValueError('invalid elapsed construction time')
    routes = path_points(scene)
    mounted = routes['mounted']
    mounted_length = sum(math.dist(a,b) for a,b in zip(mounted,mounted[1:]))
    mounted_time = mounted_length/scene['control']['mounted_speed_mps']
    if not scene['dismount_enabled']:
        pose = _route_pose(mounted, elapsed_s*scene['control']['mounted_speed_mps'])
        phase = ('turn_complete' if pose[3] else
                 'mounted_approach' if elapsed_s*scene['control']['mounted_speed_mps'] <
                    scene['dismount_x_m']-scene['approach_x_m'] else 'mounted_reversal')
        return {'operator': pose[:3], 'bicycle': pose[:3], 'phase': phase}
    dismount_pose = _route_pose(mounted, mounted_length)[:3]
    if elapsed_s < mounted_time:
        pose = _route_pose(mounted, elapsed_s*scene['control']['mounted_speed_mps'])
        return {'operator': pose[:3], 'bicycle': pose[:3],
                'phase': 'mounted_approach'}
    afoot_elapsed = elapsed_s-mounted_time-scene['control']['dismount_hold_s']
    if afoot_elapsed <= 0:
        return {'operator': dismount_pose, 'bicycle': dismount_pose,
                'phase': 'dismount_hold'}
    pose = _route_pose(routes['afoot'],
                       afoot_elapsed*scene['control']['afoot_speed_mps'])
    separated = math.dist(pose[:2], dismount_pose[:2]) >= 1.0
    phase = 'turn_complete' if pose[3] else ('afoot_reversal' if separated
                                             else 'dismount_hold')
    return {'operator': pose[:3], 'bicycle': dismount_pose,
            'phase': phase}


def check():
    scene = load_scene()
    points = path_points(scene)
    if scene['dismount_enabled']:
        assert points['mounted'][-1] == points['afoot'][0]
        assert phase_at(scene, scene['turn_x_m'], 0) == 'dismount_hold'
        assert phase_at(scene, scene['turn_x_m'], scene['control']['dismount_hold_s']) == 'afoot_reversal'
    else:
        assert not points['afoot']
        assert phase_at(scene, scene['turn_x_m'], 0) == 'mounted_reversal'
    print(json.dumps({'geometry_checked': True, 'sign_blueprint_unverified': scene['sign']['blueprint_filter']}))


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--output-dir')
    parser.add_argument('--host', default='127.0.0.1')
    parser.add_argument('--port', type=int, default=2000)
    parser.add_argument('--authorization-source')
    parser.add_argument('--scene', default=str(SCENE))
    args = parser.parse_args()
    if args.check:
        check()
    else:
        source = args.authorization_source or os.environ.get(
            'C10808_SIGN_AUTHORIZATION_SOURCE')
        if not args.output_dir or not source:
            parser.error('Native capture requires --output-dir and sign authorization source via --authorization-source or C10808_SIGN_AUTHORIZATION_SOURCE')
        from native_capture import run_native
        run_native(load_scene(args.scene), args.output_dir, args.host, args.port,
                   source)


if __name__ == '__main__':
    main()

"""Original Native actor/body samples for the prohibited-turn comparison."""
import math

PHASES = {'mounted_approach', 'dismount_hold', 'afoot_reversal',
          'mounted_reversal', 'turn_complete'}


def body(actor):
    points = actor.bounding_box.get_world_vertices(actor.get_transform())
    vertices = [[float(p.x), float(p.y), float(p.z)] for p in points]
    if len(vertices) < 4 or any(not all(math.isfinite(v) for v in point)
                                for point in vertices):
        raise ValueError('original Native actor body geometry missing')
    return vertices


def sample(actors, *, frame, time_s, phase):
    if type(frame) is not int or frame < 0 or type(time_s) not in (int, float) or not math.isfinite(time_s):
        raise ValueError('original Native frame/time missing')
    if phase not in PHASES:
        raise ValueError('unknown constructed turn phase')
    sign, bike, operator = (actors[name] for name in ('sign', 'bicycle', 'operator'))
    if len({sign.id, bike.id, operator.id}) != 3:
        raise ValueError('sign, bicycle and operator must be distinct Native actors')
    heading=float(operator.get_transform().rotation.yaw)
    if not math.isfinite(heading):
        raise ValueError('original Native operator heading missing')
    return {'frame': frame, 'time_s': time_s, 'phase': phase,
            'heading_deg': heading,
            'operator_id': operator.id, 'bicycle_id': bike.id,
            'sign_id': sign.id,
            'operator_body_vertices_m': body(operator),
            'bicycle_body_vertices_m': body(bike),
            'sign_body_vertices_m': body(sign),
            'body_source': 'original Native CARLA actor transform and bounding box',
            'phase_source': 'constructed controller phase; original body geometry independently checked'}

"""Lazy Native source capture for the two C10808 prohibited U-turn drafts.

The path controller moves the bicycle and operator as distinct actors. Physical
riding pose, sign authorization, alley status and pedestrian duties require local
review after capture; no legal status is inferred here.
"""
import hashlib
import json
import math
import queue
import shutil
import subprocess
from pathlib import Path
from types import SimpleNamespace

from native_samples import sample
from runner import path_points, spawn_scene, trajectory

CAMERAS = (('overview',1920,1080,(-10,0,40,-75)),
           ('approach',1280,720,(-10,-4,8,-20)),
           ('reference_corner',1280,720,(0,-8,14,-50)),
           ('driver_reference',1280,720,(0,0,2,0)))


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write(path, value):
    Path(path).write_text(json.dumps(value,indent=2,allow_nan=False)+'\n')


def pedestrian_context(world, native_map, operator, frame, time_s):
    """Retain Native post-dismount geography and devices without legal inference."""
    location=operator.get_transform().location
    point=[float(location.x),float(location.y),float(location.z)]
    waypoint=native_map.get_waypoint(location)
    projection=None if waypoint is None else {
        'road_id':waypoint.road_id,'lane_id':waypoint.lane_id,
        'lane_type':str(waypoint.lane_type),
        'junction_id':getattr(waypoint,'junction_id',None),
        'projection_method':'Native nearest-road waypoint; not a sidewalk or legal-crossing classification'}
    crosswalks=[[float(p.x),float(p.y),float(p.z)] for p in native_map.get_crosswalks()
                if math.dist(point[:2],[float(p.x),float(p.y)])<=40.]
    devices=[]
    for actor in world.get_actors():
        kind=str(actor.type_id)
        if not (kind.startswith('traffic.') or kind.startswith('static.prop.sign')):
            continue
        pose=actor.get_transform().location
        distance=math.dist(point[:2],[float(pose.x),float(pose.y)])
        if distance>40.:continue
        state=actor.get_state() if hasattr(actor,'get_state') else None
        devices.append({'actor_id':actor.id,'type_id':kind,
            'position_m':[float(pose.x),float(pose.y),float(pose.z)],
            'distance_to_operator_m':distance,
            'state':None if state is None else str(state)})
    devices.sort(key=lambda row:(row['distance_to_operator_m'],row['actor_id']))
    return {'frame':frame,'time_s':time_s,'operator_id':operator.id,
        'operator_position_m':point,'nearest_road_projection':projection,
        'nearby_crosswalk_vertices_m':crosswalks,'nearby_control_devices':devices,
        'source':'original Native CARLA operator transform, map and world actors',
        'pedestrian_regulation_assessment':'unresolved'}


def local_transform(carla, origin, x, y, z=0., yaw=0.):
    angle = math.radians(origin.rotation.yaw)
    location = carla.Location(
        x=origin.location.x+x*math.cos(angle)-y*math.sin(angle),
        y=origin.location.y+x*math.sin(angle)+y*math.cos(angle),
        z=origin.location.z+z)
    return carla.Transform(location,carla.Rotation(yaw=origin.rotation.yaw+yaw))


def discover_origin(native_map, scene, carla):
    """Require connected Driving support along each authored turn segment.

    Lane-center proximity is an engineering map check; it does not establish an
    alley classification, authorized sign or physical riding pose.
    """
    candidates = native_map.get_spawn_points()
    route = path_points(scene)
    anchors = route['mounted']+route['afoot']
    points = []
    for start,end in zip(anchors, anchors[1:]):
        steps = max(1,math.ceil(math.dist(start,end)))
        points.extend((start[0]+(end[0]-start[0])*i/steps,
                       start[1]+(end[1]-start[1])*i/steps)
                      for i in range(steps))
    points.append(anchors[-1])
    for origin in candidates:
        positions = [local_transform(carla,origin,*point).location for point in points]
        waypoints = [native_map.get_waypoint(position) for position in positions]
        if any(w is None for w in waypoints):
            continue
        roads = {w.road_id for w in waypoints}
        if len(roads) != 1:
            continue
        if any(str(w.lane_type).split('.')[-1] != 'Driving' for w in waypoints):
            continue
        if any(math.dist((position.x,position.y),
                         (waypoint.transform.location.x,waypoint.transform.location.y))
               > max(1.5,float(waypoint.lane_width)/2)
               for position,waypoint in zip(positions,waypoints)):
            continue
        return origin, {'road_id': next(iter(roads)),
                        'waypoint_count': len(waypoints),
                        'maximum_map_support_spacing_m': 1.0,
                        'map_source': native_map.name,
                        'alley_classification': 'unresolved_requires_local_review'}
    raise ValueError('Native map lacks connected turn geometry for authored alley path')


class Cameras:
    def __init__(self, world, operator, output, carla):
        self.sensors=[];self.encoders={};self.queues={};self.errors=[];self.closed=False
        try:
            for name,width,height,(x,y,z,pitch) in CAMERAS:
                blueprint=world.get_blueprint_library().find('sensor.camera.rgb')
                blueprint.set_attribute('image_size_x',str(width))
                blueprint.set_attribute('image_size_y',str(height))
                blueprint.set_attribute('fov','90')
                pose=carla.Transform(carla.Location(x=x,y=y,z=z),
                                     carla.Rotation(pitch=pitch))
                sensor=world.spawn_actor(blueprint,pose,attach_to=operator)
                if sensor is None:
                    raise ValueError('Native camera spawn failed: '+name)
                self.sensors.append(sensor)
                frames=queue.Queue(maxsize=4);self.queues[name]=frames
                def receive(image,destination=frames,label=name):
                    try:destination.put_nowait(image)
                    except queue.Full:self.errors.append('camera queue overflow: '+label)
                sensor.listen(receive)
                self.encoders[name]=subprocess.Popen(
                    ['ffmpeg','-nostdin','-hide_banner','-loglevel','error',
                     '-n','-f','rawvideo','-pixel_format','bgra',
                     '-video_size',f'{width}x{height}','-framerate','20',
                     '-i','pipe:0','-an','-c:v','ffv1','-pix_fmt','bgra',
                     str(output/(name+'.mkv'))],stdin=subprocess.PIPE,
                     stderr=subprocess.DEVNULL)
        except BaseException:
            self.close()
            raise

    def append(self,frame):
        if self.errors:raise RuntimeError('; '.join(self.errors))
        for name,*_ in CAMERAS:
            image=self.queues[name].get(timeout=15)
            if image.frame!=frame:raise ValueError('Native camera/frame mismatch: '+name)
            self.encoders[name].stdin.write(image.raw_data)

    def close(self):
        if self.closed:return
        self.closed=True;errors=[]
        for sensor in reversed(self.sensors):
            try:sensor.stop()
            except BaseException as error:errors.append(repr(error))
        for name,process in self.encoders.items():
            try:
                if process.stdin and not process.stdin.closed:process.stdin.close()
                if process.wait(timeout=180):errors.append('encoder failed: '+name)
            except BaseException as error:errors.append('encoder '+name+': '+repr(error))
        for sensor in reversed(self.sensors):
            try:sensor.destroy()
            except BaseException as error:errors.append(repr(error))
        if errors:raise RuntimeError('; '.join(errors))


class WalkerCaptureProxy:
    """Expose neutral vehicle-control fields to the pinned graph collector.

    The actual subject remains the Native walker. These fields describe neither
    propulsion nor a legal bicycle operation; scripted transforms are recorded
    separately in the original phase stream.
    """
    def __init__(self, actor):self.actor=actor
    def __getattr__(self,name):return getattr(self.actor,name)
    def get_control(self):
        return SimpleNamespace(throttle=0.,steer=0.,brake=1.,hand_brake=True,
                               reverse=False,manual_gear_shift=False,gear=0)


def run_native(scene, output, host, port, authorization_file):
    """Record actual CARLA sources only on a dedicated supplied server."""
    output=Path(output).resolve();authorization_file=Path(authorization_file).resolve()
    if not output.is_dir() or not authorization_file.is_file():
        raise ValueError('attempt directory and sign-authorization source required')
    for required in ('construction.json','runner.py'):
        if not (output/required).is_file():
            raise ValueError('Native attempt missing sealed construction source: '+required)
    import carla
    from pipeline_capture import PipelineCapture
    from worker_exchange.native_output import FrameMap, seal_capture
    from worker_exchange.world_restore import fields, equal
    client=carla.Client(host,port);client.set_timeout(30)
    world=client.get_world();native_map=world.get_map()
    origin,map_context=discover_origin(native_map,scene,carla)
    original_settings=world.get_settings();original_weather=world.get_weather()
    actors={};cameras=frame_map=pipeline=None;errors=[];phase='initializing';restored=False
    rows=0
    try:
        settings=world.get_settings();settings.synchronous_mode=True
        settings.fixed_delta_seconds=1/20;world.apply_settings(settings)
        transform=lambda x,y,z,yaw:local_transform(carla,origin,x,y,z,yaw)
        actors=spawn_scene(world,scene,transform)
        shutil.copyfile(authorization_file,output/'sign-authorization-source')
        fixed_scene={key:value for key,value in scene.items()
                     if key not in ('case_id','dismount_enabled')}
        fixed_scene_sha256=hashlib.sha256(json.dumps(
            fixed_scene,sort_keys=True,separators=(',',':')).encode()).hexdigest()
        camera_contract_sha256=hashlib.sha256(json.dumps(
            CAMERAS,sort_keys=True,separators=(',',':')).encode()).hexdigest()
        write(output/'sign-inventory.json',{
            'message':scene['sign']['message'],'erected':True,
            'sign_actor_id':actors['sign'].id,
            'sign_blueprint':actors['sign'].type_id,
            'bicycle_blueprint':actors['bicycle'].type_id,
            'operator_blueprint':actors['operator'].type_id,
            'fixed_scene_sha256':fixed_scene_sha256,
            'camera_contract_sha256':camera_contract_sha256,
            'authorization_source_sha256':sha(output/'sign-authorization-source'),
            'authorization_status':'unresolved_requires_independent_review',
            'map_context':map_context})
        write(output/'acquisition-provenance.json',{
            'provenance_kind':'native','diagnostic_fixture':False,
            'method':'original CARLA live run; scripted actor path'})
        cameras=Cameras(world,actors['operator'],output,carla)
        frame_map=FrameMap(output/'video_frames.jsonl')
        pipeline=PipelineCapture(client,WalkerCaptureProxy(actors['operator']),
                                 output,scene['case_id'])
        start=world.get_snapshot().timestamp.elapsed_seconds
        phase='capturing'
        with (output/'phase-events.jsonl').open('x',buffering=1) as events, \
             (output/'pedestrian-context.jsonl').open('x',buffering=1) as contexts:
            for index in range(round(scene.get('duration_s',30)*20)):
                requested=trajectory(scene,(index+1)/20)
                for name in ('operator','bicycle'):
                    x,y,yaw=requested[name]
                    actors[name].set_transform(transform(x,y,0,yaw))
                frame=world.tick();snapshot=world.get_snapshot()
                if frame!=snapshot.frame:raise RuntimeError('Native frame mismatch')
                elapsed=snapshot.timestamp.elapsed_seconds-start
                pipeline.capture(frame,elapsed,extra={
                    'control_provenance':'neutral walker control adapter; authored motion uses scripted actor transforms'})
                cameras.append(frame);frame_map.append(frame,elapsed)
                row=sample(actors,frame=frame,time_s=elapsed,
                           phase=requested['phase'])
                events.write(json.dumps(row,allow_nan=False)+'\n')
                context=pedestrian_context(world,native_map,actors['operator'],frame,elapsed)
                contexts.write(json.dumps(context,allow_nan=False)+'\n')
                rows+=1
        phase='closing'
        frame_map.close();frame_map=None
        pipeline.close();pipeline=None
        cameras.close();cameras=None
        capture_manifest=json.loads((output/'capture/manifest.json').read_text())
        if (capture_manifest.get('frames')!=rows or
                capture_manifest.get('extraction_confirmed') is not True):
            raise ValueError('Pinned Native graph/evidence capture incomplete')
        names=['phase-events.jsonl','pedestrian-context.jsonl','sign-inventory.json',
               'sign-authorization-source','video_frames.jsonl','trace.jsonl',
               'road.xodr','carla_recorder.log',
               *[name+'.mkv' for name,*_ in CAMERAS]]
        names += [str(path.relative_to(output)) for path in
                  (output/'capture').rglob('*') if path.is_file()]
        write(output/'acquisition.json',{name:{'kind':'original_native',
            'sha256':sha(output/name)} for name in names})
        phase='sealed'
    except BaseException as error:
        errors.append(repr(error));raise
    finally:
        for resource in (frame_map,pipeline,cameras):
            if resource:
                try:
                    if resource is pipeline:resource.close(confirmed=False)
                    else:resource.close()
                except BaseException as error:errors.append(repr(error))
        for actor in reversed(list(actors.values())):
            try:actor.destroy()
            except BaseException as error:errors.append(repr(error))
        try:
            world.apply_settings(original_settings);world.set_weather(original_weather)
            restored=all(equal(fields(world.get_settings()).get(k),v)
                         for k,v in fields(original_settings).items())
        except BaseException as error:errors.append(repr(error))
        if phase=='sealed' and not errors and restored:
            seal_capture(output,frames=rows,
                restoration={'restored':True,
                             'settings_readback':'original settings restored'},
                errors=[],encoder_exit_codes={name:0 for name,*_ in CAMERAS},
                context={'sign_inventory':'sign-inventory.json',
                         'alley_context':map_context})
        else:
            write(output/'native-run-status.json',{
                'phase':phase,'errors':errors,'settings_restored':restored,
                'common_capture_integration':'attempted through pinned PipelineCapture'})
            if phase=='sealed':raise RuntimeError('Native cleanup/restoration failed')

"""Check decoded RGB presence in all four C10808 source views.

This detects blank or missing views. It does not recognize a sign, bicycle,
mounted rider or pedestrian duty; those require independent visual review.
"""

VIEWS=((960,0,1920,1080),(0,1080,1280,720),
       (1280,1080,1280,720),(2560,1080,1280,720))


def check(frame):
    if (frame.width,frame.height)!=(3840,1800):
        raise ValueError('C10808 composed source dimensions differ')
    if len(frame.pixels)!=frame.width*frame.height*3:
        raise ValueError('C10808 decoded RGB frame is truncated')
    stride=frame.width*3
    for view,(x,y,width,height) in enumerate(VIEWS):
        visible=False
        for row in range(1,8):
            yy=y+height*row//8
            for column in range(1,8):
                xx=x+width*column//8
                offset=yy*stride+xx*3
                if any(frame.pixels[offset:offset+3]):
                    visible=True;break
            if visible:break
        if not visible:
            raise ValueError('C10808 decoded source view is blank: '+str(view))
